import{_ as c,C as h,o as a,c as m,a0 as o,b as n,w as t,a as r,E as s,a1 as l,j as d}from"./chunks/framework.CzVS_xMp.js";const u="/ai-data-center-systems/assets/ai-kpi-stack.9b86rlPn.svg",p="/ai-data-center-systems/assets/jct-critical-path.BJVc0KU3.svg",f="data:image/svg+xml;base64,",g="/ai-data-center-systems/assets/mlperf-benchmark-workflow.BvNIb38g.svg",D=JSON.parse('{"title":"Chapter 10: AI Network Performance KPIs","description":"","frontmatter":{},"headers":[],"relativePath":"network/chap10/index.md","filePath":"network/chap10/index.md","lastUpdated":1788490169000}'),b={name:"network/chap10/index.md"};function C(y,e,A,I,k,w){const i=h("Mermaid");return a(),m("div",null,[e[8]||(e[8]=o('<h1 id="chapter-10-ai-network-performance-kpis" tabindex="-1">Chapter 10: AI Network Performance KPIs <a class="header-anchor" href="#chapter-10-ai-network-performance-kpis" aria-label="Permalink to &quot;Chapter 10: AI Network Performance KPIs&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#goal">Goal</a></li><li><a href="#why-benchmarking-matters-for-ai-data-centers">Why Benchmarking Matters for AI Data Centers</a><ul><li><a href="#from-generic-data-center-kpis-to-ai-kpis">From Generic Data Center KPIs to AI KPIs</a></li><li><a href="#kpi-families">KPI Families</a></li></ul></li><li><a href="#job-completion-time-jct">Job Completion Time, JCT</a><ul><li><a href="#what-jct-includes">What JCT Includes</a></li><li><a href="#why-jct-is-a-fabric-kpi">Why JCT Is a Fabric KPI</a></li></ul></li><li><a href="#model-level-kpis">Model-Level KPIs</a><ul><li><a href="#accuracy">Accuracy</a></li><li><a href="#precision-recall-and-f1-score">Precision, Recall, and F1-Score</a></li><li><a href="#model-latency">Model Latency</a></li></ul></li><li><a href="#data-level-kpis">Data-Level KPIs</a><ul><li><a href="#data-efficiency">Data Efficiency</a></li><li><a href="#training-time">Training Time</a></li></ul></li><li><a href="#infrastructure-level-kpis">Infrastructure-Level KPIs</a><ul><li><a href="#throughput">Throughput</a></li><li><a href="#latency-and-tail-latency">Latency and Tail Latency</a></li><li><a href="#power">Power</a></li><li><a href="#efficiency">Efficiency</a></li><li><a href="#scalability">Scalability</a></li></ul></li><li><a href="#network-and-storage-signals">Network and Storage Signals</a></li><li><a href="#mlcommons-and-mlperf">MLCommons and MLPerf</a><ul><li><a href="#mlcommons-initiatives">MLCommons Initiatives</a></li><li><a href="#mlperf-benchmark-suites">MLPerf Benchmark Suites</a></li><li><a href="#closed-division-and-open-division">Closed Division and Open Division</a></li></ul></li><li><a href="#benchmarking-an-ai-data-center">Benchmarking an AI Data Center</a><ul><li><a href="#benchmark-workflow">Benchmark Workflow</a></li><li><a href="#mlperf-inference-and-loadgen">MLPerf Inference and LoadGen</a></li><li><a href="#mlperf-training-end-to-end-measurement">MLPerf Training End-to-End Measurement</a></li><li><a href="#mlperf-storage">MLPerf Storage</a></li></ul></li><li><a href="#interpreting-kpi-movement">Interpreting KPI Movement</a></li><li><a href="#operational-validation-checklist">Operational Validation Checklist</a></li><li><a href="#practical-tips-and-notes">Practical Tips and Notes</a><ul><li><a href="#do-not-optimize-a-single-kpi-alone">Do Not Optimize a Single KPI Alone</a></li><li><a href="#keep-benchmark-and-production-metrics-separate">Keep Benchmark and Production Metrics Separate</a></li><li><a href="#use-symptom-tables-as-triage-not-proof">Use Symptom Tables as Triage, Not Proof</a></li></ul></li><li><a href="#chapter-summary">Chapter Summary</a></li><li><a href="#key-terms">Key Terms</a></li><li><a href="#qa">Q&amp;A</a></li><li><a href="#references">References</a></li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>This chapter explains how to evaluate AI data center performance with KPIs and standardized benchmarks.</p><p>The core idea is:</p><blockquote><p>In an AI data center, performance is not captured by server availability or raw link speed alone. The most important question is whether the whole system can move data, train models, serve inference, and scale while preserving model quality, latency targets, and power efficiency.</p></blockquote><p>The chapter focuses on these topics:</p><ul><li>Why benchmarking is needed for AI/ML infrastructure</li><li>Job Completion Time, JCT, as a core training KPI</li><li>Model-level KPIs such as accuracy, precision, recall, F1-score, and inference latency</li><li>Data-level KPIs such as data efficiency and training time</li><li>Infrastructure-level KPIs such as throughput, latency, power, efficiency, and scalability</li><li>Network and storage counters that explain KPI movement</li><li>MLCommons and MLPerf benchmark suites</li><li>MLPerf Training, Inference, and Storage</li><li>Closed Division and Open Division benchmark rules</li><li>How LoadGen drives inference benchmarks</li><li>How to interpret benchmark results operationally</li></ul><p><img src="'+u+'" alt="AI data center KPI stack"></p>',10)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-301",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20W%5BAI%20workload%3Cbr%2F%3Etraining%20or%20inference%5D%20--%3E%20M%5BModel%20KPIs%3Cbr%2F%3Equality%20and%20latency%5D%0A%20%20%20%20W%20--%3E%20D%5BData%20KPIs%3Cbr%2F%3Equality%20and%20supply%5D%0A%20%20%20%20W%20--%3E%20I%5BInfrastructure%20KPIs%3Cbr%2F%3Ethroughput%2C%20power%2C%20scale%5D%0A%20%20%20%20I%20--%3E%20N%5BNetwork%20and%20storage%20signals%3Cbr%2F%3EECN%2C%20PFC%2C%20drops%2C%20checkpoint%5D%0A%20%20%20%20M%20--%3E%20R%5BValid%20result%3Cbr%2F%3Etarget%20quality%20reached%5D%0A%20%20%20%20D%20--%3E%20R%0A%20%20%20%20N%20--%3E%20R%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20W%20primary%0A%20%20%20%20class%20M%2CD%2CI%20secondary%0A%20%20%20%20class%20N%20note%0A%20%20%20%20class%20R%20accent%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=o('<h2 id="why-benchmarking-matters-for-ai-data-centers" tabindex="-1">Why Benchmarking Matters for AI Data Centers <a class="header-anchor" href="#why-benchmarking-matters-for-ai-data-centers" aria-label="Permalink to &quot;Why Benchmarking Matters for AI Data Centers&quot;">​</a></h2><p>Benchmarking is useful whenever a system evolves and many design options must be compared. AI infrastructure evolves quickly: GPU generations change, model architectures change, precision formats change, network fabrics change, and storage paths change.</p><p>Without shared metrics, it is easy to optimize the wrong thing. A fabric may show high link utilization but still increase training time. A GPU node may show high peak FLOPS but still miss inference latency targets. A storage system may show high sequential bandwidth but still starve dataloaders because metadata operations or small-file reads are slow.</p><p>Benchmarking gives operators a structured way to answer questions such as:</p><ul><li>Which system trains the model to target accuracy faster?</li><li>Which inference stack serves more queries while meeting latency constraints?</li><li>Which storage design keeps GPUs fed during training?</li><li>Which fabric change improves goodput instead of only increasing raw bandwidth?</li><li>Which optimization lowers cost per token or FLOPS per watt?</li><li>Are results reproducible across runs and comparable across platforms?</li></ul><h3 id="from-generic-data-center-kpis-to-ai-kpis" tabindex="-1">From Generic Data Center KPIs to AI KPIs <a class="header-anchor" href="#from-generic-data-center-kpis-to-ai-kpis" aria-label="Permalink to &quot;From Generic Data Center KPIs to AI KPIs&quot;">​</a></h3><p>Traditional data center KPIs often emphasize availability, power, capacity, and utilization. Those still matter, but AI data centers need additional application-level and fabric-level signals.</p><table tabindex="0"><thead><tr><th>Traditional KPI</th><th>Why It Is Not Enough for AI</th></tr></thead><tbody><tr><td>Server uptime</td><td>A server can be up while GPUs are idle because data, communication, or storage is slow.</td></tr><tr><td>Average link utilization</td><td>Average utilization can hide microbursts, incast, tail latency, and flow unfairness.</td></tr><tr><td>Total power draw</td><td>Power must be compared with useful output such as tokens, samples, or FLOPS.</td></tr><tr><td>CPU utilization</td><td>AI bottlenecks may sit in GPU kernels, collectives, NIC queues, PCIe, storage, or metadata.</td></tr><tr><td>Capacity provisioned</td><td>Provisioned capacity does not prove that the workload reaches target quality faster.</td></tr></tbody></table><p>AI KPIs must connect infrastructure behavior to model and workload outcomes. The same cluster should be evaluated from several angles: model quality, data pipeline behavior, infrastructure throughput, network health, power, and scalability.</p><h3 id="kpi-families" tabindex="-1">KPI Families <a class="header-anchor" href="#kpi-families" aria-label="Permalink to &quot;KPI Families&quot;">​</a></h3><p>The chapter groups AI data center KPIs into model, data, and infrastructure families.</p><table tabindex="0"><thead><tr><th>Family</th><th>Main Question</th><th>Example KPIs</th></tr></thead><tbody><tr><td>Model</td><td>Does the model produce correct or useful output?</td><td>Accuracy, precision, recall, F1-score, MAP, NDCG, inference latency</td></tr><tr><td>Data</td><td>Is the training or inference data useful and supplied fast enough?</td><td>Data efficiency, data loading performance, time to train</td></tr><tr><td>Infrastructure</td><td>Can the system execute the workload quickly, efficiently, and at scale?</td><td>JCT, throughput, latency, power, FLOPS/Watt, QPS/Watt, scaling efficiency</td></tr><tr><td>Network and storage</td><td>What infrastructure signals explain the workload result?</td><td>ECN marks, PFC pauses, CNPs, drops, queue occupancy, checkpoint write time</td></tr></tbody></table>',12)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-476",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20K%5BAI%20data%20center%20KPIs%5D%20--%3E%20M%5BModel%3Cbr%2F%3Equality%20and%20prediction%20behavior%5D%0A%20%20%20%20K%20--%3E%20D%5BData%3Cbr%2F%3Equality%20and%20input%20pipeline%5D%0A%20%20%20%20K%20--%3E%20I%5BInfrastructure%3Cbr%2F%3Esystem%20execution%5D%0A%20%20%20%20I%20--%3E%20F%5BFabric%20and%20storage%3Cbr%2F%3Eroot-cause%20signals%5D%0A%0A%20%20%20%20M%20--%3E%20A%5BAccuracy%2C%20precision%2C%3Cbr%2F%3Erecall%2C%20F1%2C%20MAP%5D%0A%20%20%20%20D%20--%3E%20T%5BData%20efficiency%2C%3Cbr%2F%3Edata%20loading%2C%20training%20time%5D%0A%20%20%20%20I%20--%3E%20P%5BJCT%2C%20throughput%2C%3Cbr%2F%3Elatency%2C%20power%2C%20scale%5D%0A%20%20%20%20F%20--%3E%20C%5BECN%2C%20PFC%2C%20CNP%2C%3Cbr%2F%3Edrops%2C%20queues%2C%20checkpoints%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20K%20primary%0A%20%20%20%20class%20M%2CD%2CI%20secondary%0A%20%20%20%20class%20F%20accent%0A%20%20%20%20class%20A%2CT%2CP%2CC%20note%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=o('<h2 id="job-completion-time-jct" tabindex="-1">Job Completion Time, JCT <a class="header-anchor" href="#job-completion-time-jct" aria-label="Permalink to &quot;Job Completion Time, JCT&quot;">​</a></h2><p>Job Completion Time, JCT, is the total time a job takes from start to useful completion. In training, the useful completion point is normally a target accuracy or quality threshold.</p><p>In AI training fabrics, JCT is one of the most important top-level KPIs because it captures the combined effect of:</p><ul><li>Data loading</li><li>Forward pass</li><li>Backward pass</li><li>Gradient synchronization</li><li>GPU-to-GPU communication</li><li>Optimizer step</li><li>Checkpoint writing</li><li>Validation and accuracy checks</li><li>Failure recovery or restart time</li></ul><p><img src="'+p+'" alt="JCT critical path for distributed training"></p><h3 id="what-jct-includes" tabindex="-1">What JCT Includes <a class="header-anchor" href="#what-jct-includes" aria-label="Permalink to &quot;What JCT Includes&quot;">​</a></h3><p>JCT is not only compute time. It includes the pauses and waits introduced by the surrounding system.</p>',7)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-542",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20S%5BTraining%20job%20start%5D%20--%3E%20L%5BData%20loading%5D%0A%20%20%20%20L%20--%3E%20F%5BForward%20pass%5D%0A%20%20%20%20F%20--%3E%20B%5BBackward%20pass%5D%0A%20%20%20%20B%20--%3E%20C%5BAllReduce%20%2F%20sync%5D%0A%20%20%20%20C%20--%3E%20O%5BOptimizer%20step%5D%0A%20%20%20%20O%20--%3E%20P%5BCheckpoint%20write%5D%0A%20%20%20%20P%20--%3E%20V%5BValidation%20%2F%20accuracy%20check%5D%0A%20%20%20%20V%20--%3E%20Q%5BTarget%20quality%20reached%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20S%20primary%0A%20%20%20%20class%20L%2CF%2CB%2CO%2CV%20secondary%0A%20%20%20%20class%20C%2CP%20accent%0A%20%20%20%20class%20Q%20primary%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[r(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=o('<p>Operationally, JCT increases when:</p><ul><li>GPU kernels are inefficient.</li><li>Collectives wait on slow ranks.</li><li>Network congestion increases synchronization time.</li><li>Dataloader workers cannot feed GPUs.</li><li>Storage throughput or metadata latency is poor.</li><li>Checkpoint writes pause the training loop.</li><li>Failures force replay from older checkpoints.</li><li>Scaling efficiency drops as more GPUs are added.</li></ul><h3 id="why-jct-is-a-fabric-kpi" tabindex="-1">Why JCT Is a Fabric KPI <a class="header-anchor" href="#why-jct-is-a-fabric-kpi" aria-label="Permalink to &quot;Why JCT Is a Fabric KPI&quot;">​</a></h3><p>JCT is often discussed as a training metric, but it is also a network and storage KPI.</p><p>In distributed training, the fabric affects JCT through communication phases such as AllReduce, AllGather, ReduceScatter, parameter exchange, and checkpoint traffic. If the network creates stragglers, the fastest GPUs wait for the slowest rank. If the storage path is slow, the entire job can pause during checkpoint writes or dataset reads.</p><p>The practical lesson is:</p><blockquote><p>Do not validate an AI fabric only with link bandwidth. Validate whether the fabric reduces JCT for real training jobs.</p></blockquote><h2 id="model-level-kpis" tabindex="-1">Model-Level KPIs <a class="header-anchor" href="#model-level-kpis" aria-label="Permalink to &quot;Model-Level KPIs&quot;">​</a></h2><p>Model KPIs measure whether the model output is correct, useful, and timely. These KPIs prevent an infrastructure benchmark from rewarding a system that is fast but produces invalid or low-quality results.</p><h3 id="accuracy" tabindex="-1">Accuracy <a class="header-anchor" href="#accuracy" aria-label="Permalink to &quot;Accuracy&quot;">​</a></h3><p>Accuracy measures how well the model performs its intended task. The right accuracy metric depends on the workload.</p><table tabindex="0"><thead><tr><th>Workload Type</th><th>Common Metric</th></tr></thead><tbody><tr><td>Classification</td><td>Accuracy, precision, recall, F1-score</td></tr><tr><td>Regression</td><td>Mean Squared Error, MSE</td></tr><tr><td>Object detection</td><td>Mean Average Precision, MAP</td></tr><tr><td>Retrieval / ranking</td><td>Recall@k, NDCG</td></tr><tr><td>Language modeling</td><td>Perplexity, loss, task-specific quality target</td></tr></tbody></table><p>In benchmarking, accuracy matters because speed without model quality is not a valid result. MLPerf-style benchmarks usually define a target quality metric, and a run is valid only if the system reaches that target.</p><h3 id="precision-recall-and-f1-score" tabindex="-1">Precision, Recall, and F1-Score <a class="header-anchor" href="#precision-recall-and-f1-score" aria-label="Permalink to &quot;Precision, Recall, and F1-Score&quot;">​</a></h3><p>Precision and recall explain different kinds of correctness.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Meaning</th><th>Useful When</th></tr></thead><tbody><tr><td>Precision</td><td>Of the items predicted positive, how many were correct?</td><td>False positives are expensive.</td></tr><tr><td>Recall</td><td>Of the true positives, how many did the model find?</td><td>Missing positives is expensive.</td></tr><tr><td>F1-score</td><td>Harmonic mean of precision and recall</td><td>Both false positives and false negatives matter.</td></tr></tbody></table><p>For example, a model can have high precision but poor recall if it predicts only a small number of very obvious positives. Another model can have high recall but poor precision if it predicts too many positives. Infrastructure benchmarking should preserve the model-quality target instead of hiding these trade-offs.</p><h3 id="model-latency" tabindex="-1">Model Latency <a class="header-anchor" href="#model-latency" aria-label="Permalink to &quot;Model Latency&quot;">​</a></h3><p>Model latency is the time between request arrival and output availability. In inference systems, it is usually more important than total job completion time.</p><p>Latency can include:</p><ul><li>Frontend request handling</li><li>Queueing and batching delay</li><li>Tokenization or preprocessing</li><li>GPU execution</li><li>KV cache access</li><li>Postprocessing</li><li>Network response time</li></ul><p>For LLM inference, latency should usually be split into prefill latency, time to first token, inter-token latency, and end-to-end latency. A single average latency number can hide user-visible tail behavior.</p><h2 id="data-level-kpis" tabindex="-1">Data-Level KPIs <a class="header-anchor" href="#data-level-kpis" aria-label="Permalink to &quot;Data-Level KPIs&quot;">​</a></h2><p>Data KPIs measure whether the data is useful, diverse, deduplicated, and delivered to the model fast enough.</p><h3 id="data-efficiency" tabindex="-1">Data Efficiency <a class="header-anchor" href="#data-efficiency" aria-label="Permalink to &quot;Data Efficiency&quot;">​</a></h3><p>Data efficiency describes how much useful learning signal is obtained from the data. Large datasets are not automatically good datasets.</p><p>Important questions:</p><ul><li>Is the data diverse enough to cover the scenarios that matter?</li><li>Is there too much duplicate or near-duplicate data?</li><li>Is the labeling or curation quality high enough?</li><li>Does the data distribution match the target workload?</li><li>Are noisy or invalid samples increasing training cost?</li><li>Does the data pipeline preserve reproducibility?</li></ul><p>For infrastructure teams, data efficiency matters because poor data can make hardware performance look worse than it is. The cluster may run quickly, but if the model needs many more iterations to reach quality, the end-to-end JCT remains poor.</p><h3 id="training-time" tabindex="-1">Training Time <a class="header-anchor" href="#training-time" aria-label="Permalink to &quot;Training Time&quot;">​</a></h3><p>Training time measures how long the system takes to train a model to a target quality metric.</p><p>It is affected by:</p><ul><li>GPU count and GPU generation</li><li>GPU memory capacity and bandwidth</li><li>Precision format such as FP32, BF16, FP16, FP8, or lower precision</li><li>Model architecture</li><li>Batch size and global batch behavior</li><li>Data pipeline and storage performance</li><li>Distributed communication efficiency</li><li>Checkpoint frequency and checkpoint write time</li><li>Software stack and kernel optimization</li></ul><p>Training time should be measured end to end. A benchmark that excludes data loading, storage, or communication may be useful for microanalysis, but it does not represent the real training job.</p><h2 id="infrastructure-level-kpis" tabindex="-1">Infrastructure-Level KPIs <a class="header-anchor" href="#infrastructure-level-kpis" aria-label="Permalink to &quot;Infrastructure-Level KPIs&quot;">​</a></h2><p>Infrastructure KPIs measure the ability of the data center to execute AI workloads quickly, efficiently, and at scale.</p><h3 id="throughput" tabindex="-1">Throughput <a class="header-anchor" href="#throughput" aria-label="Permalink to &quot;Throughput&quot;">​</a></h3><p>Throughput is the amount of useful work completed per unit time.</p><table tabindex="0"><thead><tr><th>Unit</th><th>Meaning</th><th>Typical Use</th></tr></thead><tbody><tr><td>OPS</td><td>Operations per second</td><td>General system work</td></tr><tr><td>FLOPS</td><td>Floating-point operations per second</td><td>Compute capability</td></tr><tr><td>QPS</td><td>Queries per second</td><td>Inference serving</td></tr><tr><td>samples/sec</td><td>Training or inference samples processed per second</td><td>ML training and inference</td></tr><tr><td>tokens/sec</td><td>LLM generation or prefill throughput</td><td>LLM inference</td></tr></tbody></table><p>Throughput can be measured at several levels:</p><ul><li>Node level</li><li>Rack level</li><li>Cluster level</li><li>Data center level</li></ul><p>High throughput is useful only when quality and latency constraints are still met. For example, an inference system may produce high QPS by increasing batch size, but that can violate p99 latency targets.</p><h3 id="latency-and-tail-latency" tabindex="-1">Latency and Tail Latency <a class="header-anchor" href="#latency-and-tail-latency" aria-label="Permalink to &quot;Latency and Tail Latency&quot;">​</a></h3><p>Latency is the elapsed time for an operation. It can be measured in milliseconds, microseconds, or nanoseconds depending on the component.</p><table tabindex="0"><thead><tr><th>Scope</th><th>Typical Unit</th><th>Example</th></tr></thead><tbody><tr><td>Application request</td><td>ms</td><td>Inference API response</td></tr><tr><td>Network / RDMA operation</td><td>us</td><td>Collective, RDMA read/write, storage IO</td></tr><tr><td>Hardware operation</td><td>ns</td><td>Device-level or memory-level timing</td></tr></tbody></table><p>Average latency is not enough. AI systems often care about p95, p99, and p999 latency because one slow rank, one slow request, or one slow checkpoint can affect the whole workload.</p><p>Tail latency can be caused by:</p><ul><li>Queue buildup</li><li>Link congestion</li><li>ECN marking and congestion control reaction</li><li>PFC pause propagation</li><li>Packet drops or retransmissions</li><li>PCIe contention</li><li>CPU scheduling noise</li><li>Storage metadata stalls</li><li>Checkpoint bursts</li></ul><h3 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power&quot;">​</a></h3><p>Power measures electrical energy consumption at different boundaries.</p><table tabindex="0"><thead><tr><th>Boundary</th><th>Example Measurement</th></tr></thead><tbody><tr><td>GPU</td><td>Per-GPU board power or accelerator telemetry</td></tr><tr><td>Server</td><td>Node power draw</td></tr><tr><td>Rack</td><td>Rack power and cooling load</td></tr><tr><td>Cluster</td><td>Total training or inference cluster draw</td></tr><tr><td>Data center</td><td>Facility-level power and cooling</td></tr></tbody></table><p>Power is important because AI infrastructure is constrained by electrical capacity, cooling capacity, and cost. A system with high peak performance may still be unattractive if power consumption makes useful work too expensive.</p><h3 id="efficiency" tabindex="-1">Efficiency <a class="header-anchor" href="#efficiency" aria-label="Permalink to &quot;Efficiency&quot;">​</a></h3><p>Efficiency compares output to input resources.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Efficiency = useful output / consumed resource</span></span></code></pre></div><p>Common forms:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Meaning</th></tr></thead><tbody><tr><td>TPW</td><td>Throughput per Watt</td></tr><tr><td>FPW</td><td>FLOPS per Watt</td></tr><tr><td>QPW</td><td>Queries per Watt</td></tr><tr><td>tokens/Watt</td><td>LLM token generation per Watt</td></tr><tr><td>samples/sec/GPU</td><td>Training throughput per GPU</td></tr><tr><td>cost per token</td><td>Serving cost normalized by output</td></tr></tbody></table><p>Efficiency helps compare systems that have different power, GPU count, cost, and performance. For example, one system may have higher total throughput, while another has better throughput per Watt.</p><h3 id="scalability" tabindex="-1">Scalability <a class="header-anchor" href="#scalability" aria-label="Permalink to &quot;Scalability&quot;">​</a></h3><p>Scalability measures whether performance improves as resources increase.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Meaning</th></tr></thead><tbody><tr><td>Speedup</td><td>How much faster the workload becomes when more resources are added</td></tr><tr><td>Scaling efficiency</td><td>Actual speedup divided by ideal speedup</td></tr><tr><td>Strong scaling</td><td>Fixed problem size, more GPUs</td></tr><tr><td>Weak scaling</td><td>Problem size grows with GPU count</td></tr></tbody></table><p>Strong scaling is useful when the workload size is fixed and the goal is to finish sooner. Weak scaling is useful when the goal is to solve larger problems as the cluster grows.</p><p>Poor scaling usually points to bottlenecks in at least one of these areas:</p><ul><li>Communication overhead</li><li>Load imbalance</li><li>Straggler ranks</li><li>Storage or dataloader limits</li><li>Checkpoint serialization</li><li>CPU overhead</li><li>Software framework limits</li><li>Network congestion or path imbalance</li></ul><h2 id="network-and-storage-signals" tabindex="-1">Network and Storage Signals <a class="header-anchor" href="#network-and-storage-signals" aria-label="Permalink to &quot;Network and Storage Signals&quot;">​</a></h2><p>Top-level KPIs show the outcome. Network and storage signals explain why the outcome moved.</p><table tabindex="0"><thead><tr><th>Signal</th><th>What It Can Explain</th></tr></thead><tbody><tr><td>GPU communication time</td><td>Whether collectives are dominating JCT</td></tr><tr><td>AllReduce / AllGather duration</td><td>Whether synchronization is slowing training</td></tr><tr><td>ECN mark count</td><td>Whether RoCEv2 congestion is being signaled</td></tr><tr><td>CNP count</td><td>Whether DCQCN congestion notification is active</td></tr><tr><td>PFC pause count</td><td>Whether the lossless fabric is pausing traffic</td></tr><tr><td>Packet drops</td><td>Whether RoCEv2 or TCP traffic is experiencing loss</td></tr><tr><td>RDMA retransmission</td><td>Whether reliable RDMA is recovering from loss or timeout</td></tr><tr><td>Link utilization</td><td>Whether spine, leaf, or rail links are saturated</td></tr><tr><td>Queue occupancy</td><td>Whether switch buffers are building pressure</td></tr><tr><td>Storage read throughput</td><td>Whether dataloaders can feed GPUs</td></tr><tr><td>Storage write throughput</td><td>Whether checkpoint writes can finish quickly</td></tr><tr><td>Checkpoint write time</td><td>Whether training pauses are caused by storage</td></tr></tbody></table><p>These counters should be correlated with job-level metrics such as GPU utilization, step time, p99 step time, JCT, and inference latency.</p><p><img src="'+f+'" alt="Network and storage KPI signal map"></p>',69)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-1472",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20K%5BTop-level%20KPI%20moves%5D%20--%3E%20Q%7BWhich%20path%20changed%3F%7D%0A%20%20%20%20Q%20--%3E%7CTraining%20sync%7C%20N%5BNetwork%20counters%3Cbr%2F%3EECN%2C%20CNP%2C%20PFC%2C%20drops%5D%0A%20%20%20%20Q%20--%3E%7CData%20supply%7C%20S%5BStorage%20counters%3Cbr%2F%3Eread%2C%20metadata%2C%20checkpoint%5D%0A%20%20%20%20Q%20--%3E%7CCompute%7C%20G%5BGPU%20counters%3Cbr%2F%3Eutilization%2C%20memory%2C%20kernels%5D%0A%20%20%20%20N%20--%3E%20R%5BRoot-cause%20hypothesis%5D%0A%20%20%20%20S%20--%3E%20R%0A%20%20%20%20G%20--%3E%20R%0A%20%20%20%20R%20--%3E%20V%5BRe-run%20workload%3Cbr%2F%3Eand%20compare%20JCT%20or%20latency%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20K%20primary%0A%20%20%20%20class%20Q%20accent%0A%20%20%20%20class%20N%2CS%2CG%20secondary%0A%20%20%20%20class%20R%2CV%20note%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[r(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=o('<h2 id="mlcommons-and-mlperf" tabindex="-1">MLCommons and MLPerf <a class="header-anchor" href="#mlcommons-and-mlperf" aria-label="Permalink to &quot;MLCommons and MLPerf&quot;">​</a></h2><p>One challenge with AI data center KPIs is comparability. Different vendors, clouds, software stacks, and model implementations can report different metrics in different ways.</p><p>MLCommons addresses this by defining common benchmark suites, datasets, rules, and review processes. Its purpose is to make AI system measurement fair, useful, and reproducible.</p><p><img src="'+g+'" alt="MLPerf benchmark workflow"></p><p>MLCommons goals include:</p><ul><li>Fair comparison across systems</li><li>Useful measurement that advances ML progress</li><li>Reproducible results</li><li>Benefits for commercial and research communities</li><li>Reasonable benchmarking cost so more participants can join</li></ul><h3 id="mlcommons-initiatives" tabindex="-1">MLCommons Initiatives <a class="header-anchor" href="#mlcommons-initiatives" aria-label="Permalink to &quot;MLCommons Initiatives&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Initiative</th><th>Purpose</th></tr></thead><tbody><tr><td>MLPerf</td><td>Benchmark suites for training, inference, storage, HPC, and related AI workloads</td></tr><tr><td>MLCube</td><td>Packaging and portability framework for reproducible ML workloads</td></tr><tr><td>PAIR</td><td>People + AI Research program supporting research, education, and community collaboration</td></tr></tbody></table><h3 id="mlperf-benchmark-suites" tabindex="-1">MLPerf Benchmark Suites <a class="header-anchor" href="#mlperf-benchmark-suites" aria-label="Permalink to &quot;MLPerf Benchmark Suites&quot;">​</a></h3><p>MLPerf is the main benchmark suite discussed in the chapter.</p><table tabindex="0"><thead><tr><th>Suite</th><th>What It Measures</th><th>Core Question</th></tr></thead><tbody><tr><td>MLPerf Training</td><td>Time to train to a target quality metric</td><td>How fast can the system train the model correctly?</td></tr><tr><td>MLPerf Inference</td><td>Throughput and latency for trained model serving</td><td>How fast can the system answer requests while meeting accuracy and latency constraints?</td></tr><tr><td>MLPerf Storage</td><td>Storage system ability to supply training data</td><td>Can storage keep the training workload fed?</td></tr><tr><td>MLPerf HPC</td><td>Scientific and HPC-oriented ML workloads</td><td>How well does the system handle HPC AI workloads?</td></tr></tbody></table><p>The important point is that MLPerf does not only measure raw speed. Valid results must satisfy the benchmark&#39;s accuracy or quality requirement.</p><h3 id="closed-division-and-open-division" tabindex="-1">Closed Division and Open Division <a class="header-anchor" href="#closed-division-and-open-division" aria-label="Permalink to &quot;Closed Division and Open Division&quot;">​</a></h3><p>MLPerf uses divisions to separate direct system comparison from research or algorithmic innovation.</p><table tabindex="0"><thead><tr><th>Division</th><th>Rules</th><th>Best Use</th></tr></thead><tbody><tr><td>Closed Division</td><td>Fixed model, dataset, target quality, and reference implementation constraints</td><td>Direct hardware/software comparison</td></tr><tr><td>Open Division</td><td>Allows different models or methods if the target quality requirement is met</td><td>Demonstrating new techniques or algorithmic improvements</td></tr></tbody></table><p>Closed Division is stronger for apples-to-apples comparison. Open Division is useful when the goal is to show that a new method can reach the same quality target more efficiently.</p><h2 id="benchmarking-an-ai-data-center" tabindex="-1">Benchmarking an AI Data Center <a class="header-anchor" href="#benchmarking-an-ai-data-center" aria-label="Permalink to &quot;Benchmarking an AI Data Center&quot;">​</a></h2><p>Benchmarking an AI data center is a multi-step process. The exact method depends on whether the benchmark targets training, inference, or storage, but the structure is similar.</p><h3 id="benchmark-workflow" tabindex="-1">Benchmark Workflow <a class="header-anchor" href="#benchmark-workflow" aria-label="Permalink to &quot;Benchmark Workflow&quot;">​</a></h3>',19)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-1683",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20B%5BChoose%20benchmark%20suite%3Cbr%2F%3Etraining%2C%20inference%2C%20storage%5D%20--%3E%20D%5BChoose%20division%3Cbr%2F%3Eclosed%20or%20open%5D%0A%20%20%20%20D%20--%3E%20H%5BSet%20up%20system%3Cbr%2F%3EGPU%2C%20CPU%2C%20network%2C%20storage%5D%0A%20%20%20%20H%20--%3E%20S%5BSet%20up%20software%3Cbr%2F%3EOS%2C%20drivers%2C%20framework%2C%20libraries%5D%0A%20%20%20%20S%20--%3E%20C%5BUse%20reference%20code%3Cbr%2F%3Emodel%2C%20dataset%2C%20harness%5D%0A%20%20%20%20C%20--%3E%20E%5BExecute%20benchmark%5D%0A%20%20%20%20E%20--%3E%20A%5BValidate%20accuracy%3Cbr%2F%3Eor%20target%20quality%5D%0A%20%20%20%20A%20--%3E%20R%5BSubmit%20results%3Cbr%2F%3Eand%20code%5D%0A%20%20%20%20R%20--%3E%20P%5BPeer%20review%3Cbr%2F%3Eand%20publication%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20B%20primary%0A%20%20%20%20class%20D%2CH%2CS%2CC%2CE%20secondary%0A%20%20%20%20class%20A%20accent%0A%20%20%20%20class%20R%2CP%20note%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[r(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=o('<p>The workflow should capture:</p><ul><li>Hardware configuration: GPU, CPU, memory, NIC, storage, switches</li><li>Software configuration: OS, driver, CUDA or accelerator runtime, framework, benchmark code</li><li>Network configuration: topology, link speed, congestion control, MTU, routing, load balancing</li><li>Storage configuration: filesystem, protocol, queue depth, metadata layout, dataset placement</li><li>Accuracy or quality target</li><li>Result logs and reproducibility artifacts</li></ul><h3 id="mlperf-inference-and-loadgen" tabindex="-1">MLPerf Inference and LoadGen <a class="header-anchor" href="#mlperf-inference-and-loadgen" aria-label="Permalink to &quot;MLPerf Inference and LoadGen&quot;">​</a></h3><p>MLPerf Inference uses LoadGen to issue queries to the System Under Test, SUT. LoadGen controls request generation so that results are comparable.</p>',4)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-1725",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20L%5BMLPerf%20LoadGen%5D%20--%3E%7Cqueries%7C%20S%5BSUT%3Cbr%2F%3Esystem%20under%20test%5D%0A%20%20%20%20S%20--%3E%20M%5BTrained%20model%5D%0A%20%20%20%20M%20--%3E%20S%0A%20%20%20%20S%20--%3E%7Cresponses%7C%20L%0A%20%20%20%20L%20--%3E%20R%5BResults%3Cbr%2F%3EQPS%2C%20latency%2C%20accuracy%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20L%20primary%0A%20%20%20%20class%20S%20secondary%0A%20%20%20%20class%20M%20note%0A%20%20%20%20class%20R%20accent%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[r(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=o('<p>The data center inference benchmark commonly uses two scenarios.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Query Pattern</th><th>Main Measurement</th></tr></thead><tbody><tr><td>Offline</td><td>All queries are available at once</td><td>Maximum throughput</td></tr><tr><td>Server</td><td>Queries arrive according to a Poisson distribution</td><td>Throughput under latency constraints</td></tr></tbody></table><p>Inference results usually require both:</p><ul><li>A performance run, such as QPS or samples/sec</li><li>An accuracy run proving that the model output meets the required target</li></ul><h3 id="mlperf-training-end-to-end-measurement" tabindex="-1">MLPerf Training End-to-End Measurement <a class="header-anchor" href="#mlperf-training-end-to-end-measurement" aria-label="Permalink to &quot;MLPerf Training End-to-End Measurement&quot;">​</a></h3><p>MLPerf Training measures time to train to a predefined target quality metric.</p><p>The timing is end to end:</p><ol><li>Dataset loading begins.</li><li>Distributed training runs.</li><li>Compute and communication proceed across the system.</li><li>Validation checks whether the target quality has been reached.</li><li>The benchmark stops when the target quality condition is satisfied.</li></ol><p>This structure matters because it includes data pipeline, storage, GPU compute, distributed communication, and software framework behavior.</p>',9)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-1822",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20D%5BDataset%20loading%5D%20--%3E%20T%5BDistributed%20training%5D%0A%20%20%20%20T%20--%3E%20C%5BCompute%20%2B%20communication%5D%0A%20%20%20%20C%20--%3E%20V%5BValidation%5D%0A%20%20%20%20V%20--%3E%20Q%7BTarget%20quality%3Cbr%2F%3Ereached%3F%7D%0A%20%20%20%20Q%20--%3E%7CNo%7C%20T%0A%20%20%20%20Q%20--%3E%7CYes%7C%20R%5BTime%20to%20train%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20D%2CT%2CC%2CV%20secondary%0A%20%20%20%20class%20Q%20accent%0A%20%20%20%20class%20R%20primary%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[r(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=d("p",null,"From a network engineer's view, the training benchmark is useful because it exposes whether the fabric scales with the workload. If more GPUs do not reduce time to train as expected, the bottleneck may be communication, storage, framework overhead, or load imbalance.",-1)),e[16]||(e[16]=d("h3",{id:"mlperf-storage",tabindex:"-1"},[r("MLPerf Storage "),d("a",{class:"header-anchor",href:"#mlperf-storage","aria-label":'Permalink to "MLPerf Storage"'},"​")],-1)),e[17]||(e[17]=d("p",null,"MLPerf Storage measures how quickly a storage system can supply training data.",-1)),e[18]||(e[18]=d("p",null,"The core question is:",-1)),e[19]||(e[19]=d("blockquote",null,[d("p",null,"Can the storage system feed the training job fast enough that GPUs are not waiting for input data?")],-1)),(a(),n(l,null,{default:t(()=>[s(i,{id:"mermaid-1840",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20S%5BStorage%20system%5D%20--%3E%20P%5BTraining%20data%20supply%5D%0A%20%20%20%20P%20--%3E%20G%5BGPU%20training%20job%5D%0A%20%20%20%20G%20--%3E%20K%5BStep%20time%20and%20GPU%20utilization%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20S%20primary%0A%20%20%20%20class%20P%20accent%0A%20%20%20%20class%20G%20secondary%0A%20%20%20%20class%20K%20note%0A"})]),fallback:t(()=>[...e[7]||(e[7]=[r(" Loading... ",-1)])]),_:1})),e[20]||(e[20]=o('<p>Storage benchmarking should be interpreted together with:</p><ul><li>GPU idle time</li><li>Dataloader wait time</li><li>Training step time</li><li>Checkpoint write time</li><li>Metadata latency</li><li>Storage network utilization</li><li>RDMA or TCP transport counters</li></ul><h2 id="interpreting-kpi-movement" tabindex="-1">Interpreting KPI Movement <a class="header-anchor" href="#interpreting-kpi-movement" aria-label="Permalink to &quot;Interpreting KPI Movement&quot;">​</a></h2><p>A KPI should lead to an operational hypothesis. The table below maps common symptoms to first checks.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>First Checks</th></tr></thead><tbody><tr><td>JCT increases</td><td>Step time, slow ranks, collective duration, checkpoint time, dataloader wait</td></tr><tr><td>Time to train does not improve with more GPUs</td><td>Scaling efficiency, AllReduce time, fabric congestion, batch-size behavior</td></tr><tr><td>Throughput is high but latency fails</td><td>Batch size, queue depth, scheduler policy, p99 and p999 latency</td></tr><tr><td>GPU utilization is low</td><td>Dataloader, storage read latency, CPU preprocessing, PCIe, network stalls</td></tr><tr><td>ECN/CNP counters spike</td><td>RoCEv2 congestion, DCQCN profile, incast, path imbalance</td></tr><tr><td>PFC pauses increase</td><td>Lossless class pressure, head-of-line blocking, buffer allocation</td></tr><tr><td>Packet drops appear</td><td>Queue overflow, incorrect lossless configuration, routing imbalance</td></tr><tr><td>Checkpoint pauses dominate</td><td>Storage write bandwidth, metadata path, checkpoint frequency, filesystem layout</td></tr><tr><td>Power rises without useful throughput</td><td>GPU clocks, low utilization, cooling constraints, inefficient batch or precision</td></tr><tr><td>Accuracy target is unstable</td><td>Data quality, random seeds, precision mode, hyperparameters, benchmark rule compliance</td></tr></tbody></table><h2 id="operational-validation-checklist" tabindex="-1">Operational Validation Checklist <a class="header-anchor" href="#operational-validation-checklist" aria-label="Permalink to &quot;Operational Validation Checklist&quot;">​</a></h2><p>Use this checklist when evaluating AI data center KPIs or benchmark results.</p><ul><li>Define whether the workload is training, inference, storage, or mixed.</li><li>Record the target quality or accuracy condition before measuring speed.</li><li>Measure JCT or time to train for training workloads.</li><li>Split training time into data loading, compute, communication, checkpoint, and validation phases.</li><li>For inference, report both throughput and p95/p99 latency.</li><li>For LLM inference, separate prefill, time to first token, inter-token latency, and total latency when possible.</li><li>Report the unit clearly: FLOPS, QPS, samples/sec, tokens/sec, or OPS.</li><li>Normalize useful output by resource: per GPU, per rack, per Watt, and per dollar when needed.</li><li>Measure power at the correct boundary: GPU, node, rack, cluster, or facility.</li><li>Evaluate strong scaling and weak scaling separately.</li><li>Correlate application metrics with ECN, CNP, PFC, drops, queue occupancy, and RDMA retransmission.</li><li>Correlate dataloader wait and checkpoint time with storage read/write and metadata metrics.</li><li>Use p99 and p999, not only averages, for latency-sensitive workloads.</li><li>Keep benchmark configuration reproducible: hardware, software, model, dataset, framework, driver, and network settings.</li><li>Distinguish Closed Division-style comparison from Open Division-style innovation.</li><li>Run benchmarks more than once and investigate variance.</li><li>Treat benchmark improvement as valid only if target quality is preserved.</li></ul><h2 id="practical-tips-and-notes" tabindex="-1">Practical Tips and Notes <a class="header-anchor" href="#practical-tips-and-notes" aria-label="Permalink to &quot;Practical Tips and Notes&quot;">​</a></h2><h3 id="do-not-optimize-a-single-kpi-alone" tabindex="-1">Do Not Optimize a Single KPI Alone <a class="header-anchor" href="#do-not-optimize-a-single-kpi-alone" aria-label="Permalink to &quot;Do Not Optimize a Single KPI Alone&quot;">​</a></h3><p>AI data center KPIs are coupled. Improving one number can damage another.</p><table tabindex="0"><thead><tr><th>Optimization</th><th>What Can Go Wrong</th><th>Guardrail</th></tr></thead><tbody><tr><td>Increase inference batch size</td><td>QPS improves but p99 latency misses target</td><td>Track QPS and p99/p999 together</td></tr><tr><td>Lower precision</td><td>Throughput improves but quality target becomes unstable</td><td>Re-run accuracy or target-quality validation</td></tr><tr><td>Increase dataloader workers</td><td>GPU utilization improves but CPU or storage metadata becomes saturated</td><td>Watch CPU, storage latency, and metadata ops</td></tr><tr><td>Reduce checkpoint frequency</td><td>JCT improves until failure recovery becomes expensive</td><td>Track restart cost and maximum lost work</td></tr><tr><td>Tune ECN/PFC thresholds</td><td>Fewer marks or pauses may hide loss or increase tail latency</td><td>Correlate with drops, retransmissions, and step time</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>A benchmark result is not useful unless the quality target, latency target, and resource boundary are stated with it.</p></div><h3 id="keep-benchmark-and-production-metrics-separate" tabindex="-1">Keep Benchmark and Production Metrics Separate <a class="header-anchor" href="#keep-benchmark-and-production-metrics-separate" aria-label="Permalink to &quot;Keep Benchmark and Production Metrics Separate&quot;">​</a></h3><p>Benchmark metrics and production metrics answer different questions. Benchmarks compare systems under controlled rules. Production metrics explain whether real jobs are healthy.</p><p>Use both views:</p><table tabindex="0"><thead><tr><th>View</th><th>Useful For</th><th>Example</th></tr></thead><tbody><tr><td>Benchmark</td><td>Vendor/system comparison</td><td>MLPerf Training time to quality</td></tr><tr><td>Production job</td><td>Real workload health</td><td>JCT, p99 step time, checkpoint pause</td></tr><tr><td>Fabric telemetry</td><td>Root cause</td><td>ECN, CNP, PFC, drops, queue occupancy</td></tr><tr><td>Cost/energy</td><td>Operating trade-off</td><td>tokens/Watt, samples/sec/GPU, cost/token</td></tr></tbody></table><p>Do not mix benchmark and production conclusions casually. A system can win a benchmark and still be poorly tuned for a local dataset, job scheduler, storage layout, or inference SLO.</p><h3 id="use-symptom-tables-as-triage-not-proof" tabindex="-1">Use Symptom Tables as Triage, Not Proof <a class="header-anchor" href="#use-symptom-tables-as-triage-not-proof" aria-label="Permalink to &quot;Use Symptom Tables as Triage, Not Proof&quot;">​</a></h3><p>The symptom-to-first-check tables are starting points. They are not proof of causality.</p><p>For example, ECN/CNP spikes can indicate congestion, but the cause may be incast, path imbalance, wrong thresholds, a small number of elephant flows, or an application burst pattern. Confirm the hypothesis by correlating timestamps across application logs, GPU telemetry, NIC counters, switch queues, and storage metrics.</p><h2 id="chapter-summary" tabindex="-1">Chapter Summary <a class="header-anchor" href="#chapter-summary" aria-label="Permalink to &quot;Chapter Summary&quot;">​</a></h2><p>The main takeaways:</p><ul><li>AI data center performance must be measured with workload-aware KPIs, not only generic data center metrics.</li><li>JCT is a central KPI for training because it captures compute, communication, data loading, checkpointing, validation, and failure effects.</li><li>Model-level KPIs protect quality: accuracy, precision, recall, F1-score, MAP, NDCG, and latency.</li><li>Data-level KPIs explain whether the model receives useful data quickly enough.</li><li>Infrastructure KPIs include throughput, latency, power, efficiency, and scalability.</li><li>Network and storage counters are required to explain why top-level KPIs moved.</li><li>MLCommons provides standardized benchmark practices for fair and reproducible comparison.</li><li>MLPerf Training measures time to train to a target quality metric.</li><li>MLPerf Inference measures throughput and latency for trained models while enforcing accuracy targets.</li><li>MLPerf Storage measures whether storage can supply training data fast enough.</li><li>Closed Division supports direct comparison, while Open Division allows algorithmic innovation.</li><li>Benchmark results are useful only when they are reproducible, quality-valid, and tied back to operational signals.</li></ul><h2 id="key-terms" tabindex="-1">Key Terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>KPI</td><td>Key Performance Indicator</td></tr><tr><td>JCT</td><td>Job Completion Time</td></tr><tr><td>Time to train</td><td>Time required to train a model to a target quality metric</td></tr><tr><td>Accuracy</td><td>Degree to which model output is correct for the task</td></tr><tr><td>Precision</td><td>Fraction of positive predictions that are correct</td></tr><tr><td>Recall</td><td>Fraction of true positives that are found</td></tr><tr><td>F1-score</td><td>Harmonic mean of precision and recall</td></tr><tr><td>MAP</td><td>Mean Average Precision</td></tr><tr><td>NDCG</td><td>Normalized Discounted Cumulative Gain</td></tr><tr><td>Throughput</td><td>Useful work completed per unit time</td></tr><tr><td>QPS</td><td>Queries per second</td></tr><tr><td>FLOPS</td><td>Floating-point operations per second</td></tr><tr><td>OPS</td><td>Operations per second</td></tr><tr><td>Tail latency</td><td>High-percentile latency such as p95, p99, or p999</td></tr><tr><td>TPW</td><td>Throughput per Watt</td></tr><tr><td>FPW</td><td>FLOPS per Watt</td></tr><tr><td>QPW</td><td>Queries per Watt</td></tr><tr><td>Strong scaling</td><td>Fixed problem size with increasing resource count</td></tr><tr><td>Weak scaling</td><td>Problem size grows with resource count</td></tr><tr><td>MLCommons</td><td>Organization defining AI benchmark suites, datasets, and best practices</td></tr><tr><td>MLPerf</td><td>MLCommons benchmark suite for AI systems</td></tr><tr><td>LoadGen</td><td>MLPerf Inference load generator</td></tr><tr><td>SUT</td><td>System Under Test</td></tr><tr><td>Closed Division</td><td>MLPerf division for direct comparison under fixed constraints</td></tr><tr><td>Open Division</td><td>MLPerf division allowing different methods if quality targets are met</td></tr><tr><td>ECN</td><td>Explicit Congestion Notification</td></tr><tr><td>CNP</td><td>Congestion Notification Packet</td></tr><tr><td>PFC</td><td>Priority Flow Control</td></tr></tbody></table><h2 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A&quot;">​</a></h2><h3 id="_1-why-is-jct-important-in-ai-training-clusters" tabindex="-1">1. Why is JCT important in AI training clusters? <a class="header-anchor" href="#_1-why-is-jct-important-in-ai-training-clusters" aria-label="Permalink to &quot;1. Why is JCT important in AI training clusters?&quot;">​</a></h3><p>JCT measures how long the whole job takes to reach useful completion, usually a target accuracy or quality level. It includes compute, communication, data loading, checkpointing, validation, and waiting. This makes it a better top-level metric than peak FLOPS or link speed alone.</p><h3 id="_2-why-is-accuracy-part-of-a-performance-benchmark" tabindex="-1">2. Why is accuracy part of a performance benchmark? <a class="header-anchor" href="#_2-why-is-accuracy-part-of-a-performance-benchmark" aria-label="Permalink to &quot;2. Why is accuracy part of a performance benchmark?&quot;">​</a></h3><p>A system that runs quickly but fails the target quality requirement is not a valid AI result. Accuracy or target quality ensures that speed improvements do not come from skipping work, changing the task unfairly, or producing lower-quality output.</p><h3 id="_3-how-are-throughput-and-latency-different" tabindex="-1">3. How are throughput and latency different? <a class="header-anchor" href="#_3-how-are-throughput-and-latency-different" aria-label="Permalink to &quot;3. How are throughput and latency different?&quot;">​</a></h3><p>Throughput measures how much work is completed per unit time, such as QPS, samples/sec, or tokens/sec. Latency measures how long one operation or request takes. Training often emphasizes throughput and time to train, while inference often needs both high throughput and strict p99 latency.</p><h3 id="_4-why-should-power-be-normalized-by-useful-output" tabindex="-1">4. Why should power be normalized by useful output? <a class="header-anchor" href="#_4-why-should-power-be-normalized-by-useful-output" aria-label="Permalink to &quot;4. Why should power be normalized by useful output?&quot;">​</a></h3><p>Raw power draw does not show whether the system is efficient. FLOPS/Watt, QPS/Watt, tokens/Watt, or cost per token show how much useful work is produced for the energy consumed.</p><h3 id="_5-what-is-the-difference-between-strong-scaling-and-weak-scaling" tabindex="-1">5. What is the difference between strong scaling and weak scaling? <a class="header-anchor" href="#_5-what-is-the-difference-between-strong-scaling-and-weak-scaling" aria-label="Permalink to &quot;5. What is the difference between strong scaling and weak scaling?&quot;">​</a></h3><p>Strong scaling keeps the problem size fixed and adds more resources to finish faster. Weak scaling increases the problem size as resources are added. Poor scaling in either case points to bottlenecks such as communication overhead, storage limits, load imbalance, or software overhead.</p><h3 id="_6-what-does-mlperf-training-measure" tabindex="-1">6. What does MLPerf Training measure? <a class="header-anchor" href="#_6-what-does-mlperf-training-measure" aria-label="Permalink to &quot;6. What does MLPerf Training measure?&quot;">​</a></h3><p>MLPerf Training measures the time required to train a model to a predefined target quality metric. The benchmark is end to end, so data loading, storage, compute, communication, and validation behavior all matter.</p><h3 id="_7-what-does-mlperf-inference-measure" tabindex="-1">7. What does MLPerf Inference measure? <a class="header-anchor" href="#_7-what-does-mlperf-inference-measure" aria-label="Permalink to &quot;7. What does MLPerf Inference measure?&quot;">​</a></h3><p>MLPerf Inference measures how quickly a system can serve a trained model while meeting accuracy and latency requirements. In data center inference, common scenarios include Offline for maximum throughput and Server for latency-constrained request streams.</p><h3 id="_8-what-is-loadgen" tabindex="-1">8. What is LoadGen? <a class="header-anchor" href="#_8-what-is-loadgen" aria-label="Permalink to &quot;8. What is LoadGen?&quot;">​</a></h3><p>LoadGen is the MLPerf Inference load generator. It sends queries to the System Under Test in a controlled way, collects responses, and helps produce comparable throughput, latency, and accuracy results.</p><h3 id="_9-what-is-the-difference-between-closed-division-and-open-division" tabindex="-1">9. What is the difference between Closed Division and Open Division? <a class="header-anchor" href="#_9-what-is-the-difference-between-closed-division-and-open-division" aria-label="Permalink to &quot;9. What is the difference between Closed Division and Open Division?&quot;">​</a></h3><p>Closed Division fixes the model, dataset, and benchmark constraints to support direct comparisons. Open Division allows different models or training methods when the same target quality is achieved, so it is better for demonstrating new techniques.</p><h3 id="_10-which-network-signals-should-be-checked-when-training-performance-degrades" tabindex="-1">10. Which network signals should be checked when training performance degrades? <a class="header-anchor" href="#_10-which-network-signals-should-be-checked-when-training-performance-degrades" aria-label="Permalink to &quot;10. Which network signals should be checked when training performance degrades?&quot;">​</a></h3><p>Start with collective duration, ECN marks, CNP counts, PFC pauses, packet drops, RDMA retransmissions, queue occupancy, and link utilization. Then correlate them with GPU utilization, step time, p99 step time, checkpoint time, and JCT.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://mlcommons.org/" target="_blank" rel="noreferrer">MLCommons</a></li><li><a href="https://mlcommons.org/benchmarks/" target="_blank" rel="noreferrer">MLCommons Benchmarks</a></li><li><a href="https://github.com/mlcommons/inference" target="_blank" rel="noreferrer">MLPerf Inference GitHub Repository</a></li><li><a href="https://github.com/mlcommons/training" target="_blank" rel="noreferrer">MLPerf Training GitHub Repository</a></li><li><a href="https://github.com/mlcommons/storage" target="_blank" rel="noreferrer">MLPerf Storage GitHub Repository</a></li><li><a href="https://www.nvidia.com/en-us/data-center/resources/mlperf-benchmarks/" target="_blank" rel="noreferrer">NVIDIA, &quot;MLPerf Benchmarks&quot;</a></li><li><a href="https://lambda.ai/blog/demystifying-gpt-3" target="_blank" rel="noreferrer">Chuan Li, &quot;OpenAI&#39;s GPT-3 Language Model: A Technical Overview,&quot; Lambda, June 3, 2020</a></li></ul>',49))])}const v=c(b,[["render",C]]);export{D as __pageData,v as default};
